  (89, 'Removed image “anim.gif” from the library', '{"version":1,"exportedAt":"2026-10-24T19:22:24.195Z","site":{"name":"Hafiz Muhammad Saad","role":"UI/UX Designer & Brand Designer","bioLead":"Multi-disciplinary","bio":"product and visual designer helping ambitious founders and high-growth companies build exceptional digital products — from intuitive SaaS dashboards and mobile apps to distinctive brand system.","email":"saad.designs4@gmail.com","location":"Karachi, Pakistan","resumeUrl":null,"openToWork":true,"avatarPath":"/images/profile.png","portraitPath":"/images/portrait.png","signaturePath":"/images/signature.png","artworkPath":"/images/mazar.png"},"texts":{"about.badge":"Open to Work","about.hero.bold":"Multidisciplinary","about.hero.rest":"designer crafting distinctive digital experiences and brand identities that challenge conventions and stand out.","about.p1":"I’m a multidisciplinary designer passionate about creating digital products and visual identities that bring ideas to life. My work spans UI/UX design, web experiences, and brand identity, combining thoughtful strategy with purposeful visuals.","about.p2":"I believe great design goes beyond aesthetics. It’s about making intentional decisions, challenging the expected, and creating meaningful experiences that people remember.","about.experienceHeading":"Work Experience","about.connectLine":"I Love Connecting With People Around the World.","about.metaDescription":"Multidisciplinary designer crafting distinctive digital experiences and brand identities — about Hafiz Muhammad Saad, UI/UX designer & brand designer based in Karachi, Pakistan.","work.heading":"My Work","work.subheading":"See my top insane high quality versatile projects","work.metaDescription":"Selected projects and design engagements — brand identity, web experiences, UI/UX and visual design work by Hafiz Muhammad Saad.","footer.copyright":"2026 Hafiz Muhammad Saad | All Rights Reserved"},"projects":[{"id":"cmvmr5ql0002cqugbqe95m3x7","s