  (90, 'Removed image “alpha-test.png” from the library', '{"version":1,"exportedAt":"2026-10-24T19:22:24.263Z","site":{"name":"Hafiz Muhammad Saad","role":"UI/UX Designer & Brand Designer","bioLead":"Multi-disciplinary","bio":"product and visual designer helping ambitious founders and high-growth companies build exceptional digital products — from intuitive SaaS dashboards and mobile apps to distinctive brand system.","email":"saad.designs4@gmail.com","location":"Karachi, Pakistan","resumeUrl":null,"openToWork":true,"avatarPath":"/images/profile.png","portraitPath":"/images/portrait.png","signaturePath":"/images/signature.png","artworkPath":"/images/mazar.png"},"texts":{"about.badge":"Open to Work","about.hero.bold":"Multidisciplinary","about.hero.rest":"designer crafting distinctive digital experiences and brand identities that challenge conventions and stand out.","about.p1":"I’m a multidisciplinary designer passionate about creating digital products and visual identities that bring ideas to life. My work spans UI/UX design, web experiences, and brand identity, combining thoughtful strategy with purposeful visuals.","about.p2":"I believe great design goes beyond aesthetics. It’s about making intentional decisions, challenging the expected, and creating meaningful experiences that people remember.","about.experienceHeading":"Work Experience","about.connectLine":"I Love Connecting With People Around the World.","about.metaDescription":"Multidisciplinary designer crafting distinctive digital experiences and brand identities — about Hafiz Muhammad Saad, UI/UX designer & brand designer based in Karachi, Pakistan.","work.heading":"My Work","work.subheading":"See my top insane high quality versatile projects","work.metaDescription":"Selected projects and design engagements — brand identity, web experiences, UI/UX and visual design work by Hafiz Muhammad Saad.","footer.copyright":"2026 Hafiz Muhammad Saad | All Rights Reserved"},"projects":[{"id":"cmvmr5ql0002cqugbqe95m3x7","slug":"uplynk-pk","title":"Uplynk.pk","shortDescription":"Founding designer — web experience & brand design","role":"Founding Designer","category":"Web & Brand Design","cover":"/images/projects/uplynk-pk.png","period":"Oct 2025 - May 2026","start":"2025-10","end":"2026-05","servicesJson":"[\"Web Design\",\"Brand Identity Design\"]","url":null,"featured":true,"order":1,"homeTile":"landscape","showOnHome":true,"contentJson":"[]","contentDoc":""},{"id":"cmvmr5ql2002dqugbvdxv3q29","slug":"ai-matterz","title":"AI Matterz","shortDescription":"Founding designer — brand identity & digital product design","role":"Founding Designer","category":"Brand & Product Design","cover":"/images/projects/ai-matterz.png","period":"Dec 2025 - Present","start":"2025-12","end":null,"servicesJson":"[\"Brand Identity Design\",\"UI/UX Design\"]","url":null,"featured":true,"order":2,"homeTile":"square","showOnHome":true,"contentJson":"[{\"id\":\"b-mvkos7zz-zoycvo\",\"type\":\"heading\",\"text\":\"The Story\",\"level\":2},{\"id\":\"b-mvkoscrd-26nsi9\",\"type\":\"paragraph\",\"text\":\"As **Founding Designer** at AI Matterz I own the brand and the product surface end-to-end — from the [visual identity](https://aimatterz.io) to the interface designers touch every day. The role blends *brand thinking* with hands-on `UI craft`, shipped in tight loops with the founding team.\"},{\"id\":\"b-mvkot47p-73w9lv\",\"type\":\"image\",\"src\":\"/images/projects/ai-matterz.png\",\"alt\":\"AI Matterz brand mark on the product cover\",\"caption\":\"The cover artwork from the engagement\",\"width\":\"wide\"},{\"id\":\"b-mvkotg44-inc61p\",\"type\":\"video\",\"src\":\"https://www.youtube.com/watch?v=dQw4w9WgXcQ\",\"caption\":\"A quick tour of the design system\"},{\"id\":\"b-mvkotr4c-h7t6vv\",\"type\":\"button\",\"label\":\"Visit AI Matterz\",\"url\":\"https://aimatterz.io\",\"variant\":\"solid\"},{\"id\":\"b-mvkotv9v-9kvcbs\",\"type\":\"quote\",\"text\":\"Design is how it works — the brand and the interface a